function parseCsv(text){
 const rows=[];let row=[],value='',quoted=false;const delimiter=text.split(/\r?\n/)[0].includes(';')?';':',';
 for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(!quoted&&c===delimiter){row.push(value);value='';}else if(!quoted&&(c==='\n'||c==='\r')){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(x=>x.trim()))rows.push(row);row=[];value='';}else value+=c;}
 if(quoted)throw new Error('CSV inválido: aspas sem fechamento.');if(value||row.length){row.push(value);rows.push(row);}return rows;
}
function importPage(){return pageHeader('produtos-lanchonete','Importação de Produtos')+`<section class="import-panel"><h2>Importação de Produtos</h2><p>Selecione um arquivo CSV para importar os produtos.</p><p>Colunas: <b>nome; custo; valor; estoque; codigo_barras</b>.</p><button id="csv-template" class="legacy-button">Baixar modelo</button><form id="import-form"><label for="csv-file">Arquivo CSV</label><input id="csv-file" type="file" accept=".csv,text/csv" required><button class="legacy-button" type="submit">Importar</button><div id="import-error" class="error" role="alert" hidden></div></form></section>`;}
function downloadText(name,content,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function bindImport(){
 document.querySelector('#csv-template').onclick=()=>downloadText('modelo-produtos.csv','\uFEFFnome;custo;valor;estoque;codigo_barras\r\nÁgua mineral;2,00;5,00;20;\r\n');
 document.querySelector('#import-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const file=document.querySelector('#csv-file').files[0];if(file.size>200000)throw new Error('Use um CSV com até 200 KB.');const rows=parseCsv((await file.text()).replace(/^\uFEFF/,''));const header=rows.shift().map(x=>x.trim().toLowerCase());if(!['nome','custo','valor','estoque'].every(x=>header.includes(x)))throw new Error('Use as colunas do arquivo modelo.');const records=rows.map((row,index)=>{const get=name=>row[header.indexOf(name)]?.trim()||'';const decimal=name=>{const value=get(name);return Number(value.includes(',')?value.replaceAll('.','').replace(',','.'):value);};return{name:get('nome'),cost:decimal('custo'),value:decimal('valor'),stock:decimal('estoque'),barcode:get('codigo_barras'),status:'Ativo'};});const result=await api('/products/import',{method:'POST',body:{records}});await refresh();toast(`${result.created} produto(s) importado(s).`);go('produtos-lanchonete/listar');}catch(error){const node=document.querySelector('#import-error');node.textContent=error.message;node.hidden=false;}finally{button.disabled=false;}};
}
