function calendar(){
 const courts=all('quadras').filter(x=>x.status==='Ativo').sort((a,b)=>(a.position||0)-(b.position||0));
 const count=state.courtsPerPage||Math.min(3,courts.length)||3,pages=Math.max(1,Math.ceil(courts.length/count));state.calendarPage=Math.min(state.calendarPage||1,pages);const visible=courts.slice((state.calendarPage-1)*count,state.calendarPage*count);
 const bookings=all('agenda').filter(x=>x.date===state.date&&x.status!=='Cancelado'),hours=openingHours(all('horarios'),state.date);
 const minutes=x=>Number(x.slice(0,2))*60+Number(x.slice(3)),format=m=>`${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`;
 const occupied=new Map(visible.map(c=>[c.id,0]));
 const start=minutes(hours.start),end=minutes(hours.end),rows=[];
 if(!hours.closed)for(let min=start;min<end;min+=30){rows.push(`<tr><td>${format(min)}</td>${visible.map(c=>{
  if(occupied.get(c.id)>min)return'';
  const b=bookings.find(x=>x.courtId===c.id&&minutes(x.start)<min+30&&minutes(x.end)>min);
  if(b){const span=Math.ceil((Math.min(end,minutes(b.end))-min)/30);occupied.set(c.id,min+span*30);return `<td rowspan="${span}"><button class="booking ${b.status==='Recebido'?'paid':''}" data-kind="${esc(b.kind)}" data-booking="${esc(b.id)}"><strong>${esc(get('clientes',b.customerId)?.name||'Reserva')}</strong>${esc(b.start)} – ${esc(b.end)}<br>${money(b.value)}</button></td>`;}
  const linked=new Set();for(const block of all('bloqueios-quadras')){if(block.primaryCourtId===c.id)linked.add(block.secondaryCourtId);if(block.secondaryCourtId===c.id)linked.add(block.primaryCourtId);}
  const blocked=bookings.some(x=>linked.has(x.courtId)&&minutes(x.start)<min+30&&minutes(x.end)>min);
  return `<td>${blocked?'<span class="blocked-slot">INDISPONÍVEL</span>':`<button class="slot" data-court="${esc(c.id)}" data-time="${format(min)}" aria-label="Reservar ${esc(c.name)} às ${format(min)}">HORÁRIO DISPONÍVEL</button>`}</td>`;
 }).join('')}</tr>`);}
 return `<div class="calendar-tools">${canEdit()?'<button class="legacy-button" id="new-booking">NOVA AGENDA</button>':''}<button class="legacy-button icon" data-day="-1" aria-label="Dia anterior">«</button><button class="legacy-button" id="calendar-today">HOJE</button><button class="legacy-button icon" data-day="1" aria-label="Próximo dia">»</button><input type="date" id="calendar-date" aria-label="Data da agenda" value="${esc(state.date)}"><button id="toggle-legends" aria-expanded="${!state.legendsHidden}">LEGENDAS ${icon(state.legendsHidden?'fas fa-plus-square':'fas fa-minus-square')}</button><span class="calendar-tools-spacer"></span><label>QUADRAS A VISUALIZAR: <select id="court-count" aria-label="Quadras a visualizar">${Array.from({length:10},(_,i)=>`<option ${i+1===count?'selected':''}>${i+1}</option>`).join('')}</select></label><label>PÁGINA <select id="calendar-page" aria-label="Página de quadras">${Array.from({length:pages},(_,i)=>`<option ${i+1===state.calendarPage?'selected':''}>${i+1}</option>`).join('')}</select></label></div><section class="reference-legends" ${state.legendsHidden?'hidden':''}><h2>LEGENDA DO STATUS DO PAGAMENTO</h2><div class="payment-legends">${[['Pago','#060'],['Pago Parcial','#f60'],['Não Pago','#f00'],['Reposição','#000'],['Isento','#a2e05b'],['Crédito','#e6ad25']].map(([label,color])=>`<span>${label}<i style="border-top-color:${color}"></i></span>`).join('')}<span>Reserva Online ${icon('fas fa-r')}</span><span>Recorrência ${icon('fas fa-arrows-rotate')}</span></div><h2>TIPO DA LOCAÇÃO</h2><div class="type-legends">${[['Avulso','Avulsa'],['Mensalista','Mensalista'],['Escolinha','Aula'],['Evento','Evento'],['Day Use','Day Use']].map(([label,kind])=>`<span data-kind="${kind}">${label}</span>`).join('')}</div></section><div class="calendar-sticky-toggle"><label>Cabeçalho Acompanha a Página <input id="sticky-calendar" type="checkbox" ${state.stickyCalendar?'checked':''}></label></div>${!courts.length?'<div class="reference-empty"><div><strong>Ainda não existem quadras cadastradas!</strong><br><a href="#quadras/cadastrar">Cadastre</a> agora mesmo a primeira.</div></div>':hours.closed?'<div class="reference-empty"><div>Não há horários de funcionamento neste dia. <a href="#horarios">Alterar horários</a></div></div>':`<div class="tablewrap calendar-wrap"><table class="calendar reference-calendar ${state.stickyCalendar?'sticky-calendar':''}"><thead><tr><th>Horários</th>${visible.map(c=>`<th>${esc(c.name)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}`;
}
