 const received=rows.filter(x=>x.status==='Recebido'),income=sum(received.filter(x=>x.kind!=='Despesa')),expense=sum(received.filter(x=>x.kind==='Despesa')),pending=sum(rows.filter(x=>x.status==='Pendente'));
