function bindReports(){document.querySelector('#report-form').onsubmit=async e=>{
 e.preventDefault();const data=new FormData(e.target),button=e.submitter;button.disabled=true;
 try{
  if(data.getAll('options').some(x=>['user','customer'].includes(x)))throw new Error('Os filtros por usuário e cliente ainda não estão disponíveis nesta versão.');
  const module=data.get('module'),from=data.get('from'),to=data.get('to');if(from>to)throw new Error('Selecione um período válido.');
  const paid=data.getAll('paid'),statuses=data.get('state')==='cancelled'?['Cancelado']:data.get('state')==='reversed'?[]:[...(paid.includes('paid')?['Recebido']:[]),...(paid.includes('pending')?['Pendente']:[])];
  const options={module,from,to,dateSource:data.get('dateSource'),mode:data.get('mode'),...(module==='agenda'?{statuses,kinds:data.getAll('kinds'),origins:data.getAll('origin')}:{}),...(data.getAll('options').includes('period')?{}:{from:'',to:''})};state.reportOptions=options;
  const rows=all(module).filter(row=>{const entry=get('lancamentos','recebimento-'+row.id);const day=options.dateSource==='receipt'?(entry?.createdAt||row.date||row.dueDate||row.createdAt||'').slice(0,10):(row.date||row.dueDate||row.createdAt||'').slice(0,10);return (!options.from||day>=options.from)&&(!options.to||day<=options.to)&&(!options.statuses||options.statuses.includes(row.status))&&(!options.kinds||options.kinds.includes(row.kind))&&(!options.origins||options.origins.includes('system'));});
  const def=moduleMap[module];const node=document.querySelector('#report-results');
  node.innerHTML=`<div class="report-result-heading"><h2>${esc(def.title)}</h2><div><button class="legacy-button" id="generate-report">Gerar Arquivo</button><button class="legacy-button" id="print-report">Imprimir</button></div></div><p>${rows.length} registro(s) · Total: <strong>${money(sum(rows))}</strong></p>`+(options.mode==='summary'?`<table class="reference-table"><thead><tr><th>Situação</th><th>Quantidade</th><th>Total</th></tr></thead><tbody>${summarizeReport(rows).map(group=>`<tr><td>${esc(group.status)}</td><td>${group.count}</td><td>${money(group.value)}</td></tr>`).join('')}</tbody></table>`:referenceTable(def,rows));
  // Reports are read-only; do not show record mutation controls in printed results.
  node.querySelectorAll('.actions').forEach(x=>x.replaceChildren());
  document.querySelector('#print-report').onclick=()=>window.print();
  document.querySelector('#generate-report').onclick=async()=>{const btn=document.querySelector('#generate-report');btn.disabled=true;try{const result=await api('/reports',{method:'POST',body:options});await refresh();const link=document.createElement('a');link.href=apiBase+'/reports/'+result.id;link.download=result.name;link.click();toast('Arquivo gerado. Consulte também Arquivos Gerados.');}catch(error){toast(error.message,true);}finally{btn.disabled=false;}};
  node.scrollIntoView({block:'start',behavior:'smooth'});
 }catch(error){const node=document.querySelector('#report-error');node.textContent=error.message;node.hidden=false;}finally{button.disabled=false;}
};}
function reportFiles(){const files=state.reportFiles||[];return pageHeader('arquivos-gerados')+`<section class="report-files">${files.length?`<div class="tablewrap"><table class="reference-table"><thead><tr><th>Arquivo</th><th>Data de Cadastro</th><th>Registros</th><th>Opções</th></tr></thead><tbody>${files.map(file=>`<tr><td>${esc(file.name)}</td><td>${esc(new Date(file.createdAt).toLocaleString('pt-BR'))}</td><td>${file.count}</td><td><a href="${apiBase}/reports/${esc(file.id)}" download aria-label="Baixar ${esc(file.name)}">${icon('fas fa-download')}</a>${canEdit()?`<button class="image-action" data-delete-report="${esc(file.id)}" aria-label="Excluir arquivo ${esc(file.name)}"><img src="/assets/lixeira.png" alt="Excluir"></button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="reference-empty"><span>📝</span><div><strong>Ainda não existem arquivos gerados!</strong><br><a href="#relatorios">Gerar Relatório</a></div></div>'}<div class="form-actions"><a class="legacy-button" href="#relatorios">Gerar Relatório</a></div></section>`;}
function bindReportFiles(){document.querySelectorAll('[data-delete-report]').forEach(button=>button.onclick=async()=>{if(!confirm('Excluir este arquivo gerado?'))return;try{await api('/reports/'+button.dataset.deleteReport,{method:'DELETE'});await refresh();renderView();}catch(error){toast(error.message,true);}});}

function exportCsv(key,rows){const def=moduleMap[key];if(!def)return;const quote=x=>{let s=String(x??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return'"'+s.replaceAll('"','""')+'"';};const keys=def.columns;const lines=[keys.map(k=>quote(def.fields.find(x=>x.key===k)?.label||'Total (R$)')).join(';'),...rows.map(row=>keys.map(k=>{const f=def.fields.find(x=>x.key===k);return quote(f?.type==='ref'?get(f.ref,row[k])?.name||'':f?.type==='money'||k==='value'?Number(row[k]||0).toFixed(2).replace('.',','):row[k]);}).join(';'))];const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`${key}-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Relatório exportado.');}
function settingsPage(def){const data=state.settings[def.key]||{};return titlebar(def.title,'Configuração do seu centro esportivo')+(def.key==='reserva-online'?'<div class="notice">A publicação de reservas online depende da implementação e validação do portal público. As reservas internas já estão disponíveis na agenda.</div>':'')+`<section class="panel settings-panel"><form id="settings-form"><div class="form-grid">${def.fields.map(x=>fieldHtml(x,data)).join('')}</div><div class="dialog-footer">${state.user.role==='Administrador'?'<button class="legacy-button" type="submit">Alterar</button>':'Somente administradores podem alterar configurações.'}</div></form></section>`;}
function bindSettings(def){document.querySelector('#settings-form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{await api('/settings/'+def.key,{method:'PUT',body:Object.fromEntries(new FormData(e.target))});await refresh();toast('Configurações salvas.');}catch(err){toast(err.message,true);}finally{btn.disabled=false;}};}
window.addEventListener('hashchange',()=>{Object.assign(state,readRoute());state.query='';state.filters={};state.formTab='';state.status='';state.page=1;render();window.scrollTo(0,0);});
document.addEventListener('click',e=>{if(!e.target.closest('.navitem'))document.querySelectorAll('.navitem.open').forEach(x=>{x.classList.remove('open');x.querySelector('.navtoggle')?.setAttribute('aria-expanded','false');});if(!e.target.closest('.profile'))document.querySelector('.profile.open')?.classList.remove('open');});
dialog.addEventListener('close',()=>{dialog.innerHTML='';dialog.classList.remove('dashboard-settings-dialog');});
const financeUI=createFinanceUI({state,api,refresh,toast,esc,money,icon,dialog,go,all,get,pageHeader,canEdit});
const tenantUI=createTenantUI({api,esc,toast,pageHeader,state,financeUI});
try{const session=await api('/session');state.managed=!!session.managed;state.user=session.user;state.csrf=session.csrf;state.operationalMode=session.operationalMode;if(state.user){await refresh();render();}else if(tenantPrefix)location.replace('/entrar');else login(session.needsSetup);}catch(e){if(tenantPrefix&&e.status===401)location.replace('/entrar');else{app.innerHTML='<div class="loading">'+esc(e.message)+'<p><a href="/conta">Minhas empresas e assinatura</a></p></div>';toast(e.message,true);}}
